import numpy as np

def loss(w):
    return 0.5 * (w[0] ** 2 + 100 * w[1] ** 2)

def noisy_grad(w, rng):
    return np.array([w[0] * (1 + 0.3 * rng.normal()), 100 * w[1] + 10 * rng.normal()])

def run(opt, steps=3000, lr=0.002, seed=0):
    rng = np.random.default_rng(seed)
    w = np.array([1.0, 1.0])
    state = {}
    for t in range(1, steps + 1):
        w = opt(w, noisy_grad(w, rng), state, lr, t)
    return w

def sgd(w, g, s, lr, t):
    return w - lr * g

def momentum(w, g, s, lr, t, beta=0.9):
    s['m'] = beta * s.get('m', 0) + g
    return w - lr * s['m']

def adam(w, g, s, lr, t, b1=0.9, b2=0.999, eps=1e-8):
    s['m'] = b1 * s.get('m', 0) + (1 - b1) * g
    s['v'] = b2 * s.get('v', 0) + (1 - b2) * g ** 2
    m_hat = s['m'] / (1 - b1 ** t)
    v_hat = s['v'] / (1 - b2 ** t)
    return w - lr * m_hat / (np.sqrt(v_hat) + eps)

for name, opt in [('SGD', sgd), ('Momentum', momentum), ('Adam', adam)]:
    losses = [loss(run(opt, seed=s)) for s in range(5)]
    print(f'{name:9s} 5 个种子平均 loss = {np.mean(losses):.4e}')

g = np.array([1.0, 1.0])
v = (1 - 0.999) * g ** 2
print('首步未修正步长:', np.round(g / (np.sqrt(v) + 1e-8), 3),
      ' 修正后:', np.round(g / np.sqrt(v / (1 - 0.999)), 3))

